node -e "
const fs = require('fs');
const clover = fs.readFileSync('/var/tmp/loop-bench/runs/1642417e449d/ci-7/coverage/clover.xml', 'utf8');
const pmatch = [...clover.matchAll(/<package name=\"([^\"]+)\">[\s\S]*?<metrics statements=\"(\d+)\" coveredstatements=\"(\d+)\" conditionals=\"(\d+)\" coveredconditionals=\"(\d+)\" methods=\"(\d+)\" coveredmethods=\"(\d+)\"\/>/g)];
const excluded = ['src.orchestration', 'src.orchestration.tools', 'src.infrastructure.stores', 'src.providers.vertex', 'src.providers.mock'];
let totS = 0, covS = 0, totC = 0, covC = 0, totM = 0, covM = 0;
for (const p of pmatch) {
  const [, name, s, cs, c, cc, m, cm] = p;
  if (excluded.some(ex => name === ex || name.startsWith(ex + '.'))) continue;
  totS += +s; covS += +cs; totC += +c; covC += +cc; totM += +m; covM += +cm;
}
console.log('Global Statements:', (covS/totS*100).toFixed(2), '% (threshold 71.48)');
console.log('Global Conditionals:', (covC/totC*100).toFixed(2), '% (threshold 64.82)');
console.log('Global Methods:', (covM/totM*100).toFixed(2), '% (threshold 68.57)');
"

node -e "
const cov = JSON.parse(fs.readFileSync('/var/tmp/loop-bench/runs/1642417e449d/ci-7/coverage/coverage-final.json', 'utf8'));
for (const [k, v] of Object.entries(cov)) {
  if (k.includes('registry.ts')) {
    const s = v.s;
    const l = v.statementMap;
    // lines
    const lineHits = {};
    for (const [id, range] of Object.entries(l)) {
      const count = s[id];
      for (let line = range.start.line; line <= range.end.line; line++) {
        lineHits[line] = (lineHits[line] || 0) + count;
      }
    }
    const totalLines = Object.keys(lineHits).length;
    const coveredLines = Object.values(lineHits).filter(c => c > 0).length;
    console.log('Lines:', coveredLines, '/', totalLines, (coveredLines/totalLines*100).toFixed(2) + '% (threshold: 70.83%)');
  }
}
"
